//! DOMINO GBNF Constrained LLM Decoding for VibeScript.
//!
//! Provides deterministic grammar-constrained logit masking (GBNF) for local autoregressive
//! model inference. Guarantees that tokens generated by the Phase 8 LLM decode loop strictly
//! conform to valid VibeScript grammar rules (functions, hooks, expressions, control flow).

/// Grammar rule type in the GBNF State Machine.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum GrammarRule {
    Root,
    Program,
    Item,
    FunctionDecl,
    HookDecl,
    ConstDecl,
    Params,
    Param,
    Block,
    Statement,
    LetStmt,
    MutStmt,
    AssignStmt,
    ReturnStmt,
    IfStmt,
    WhileStmt,
    ForStmt,
    MatchStmt,
    Expr,
    BinaryExpr,
    UnaryExpr,
    PrimaryExpr,
    Literal,
    Ident,
    TypeExpr,
}

/// A DFA state tracking current grammar match progress.
#[derive(Debug, Clone)]
pub struct DominoGrammarState {
    /// Active grammar rules stack (depth <= 32 for zero-heap stack guarantee).
    rule_stack: [GrammarRule; 32],
    stack_depth: usize,
    /// Partial text buffer matching the current rule.
    partial_match: [u8; 128],
    partial_len: usize,
    /// Whether the parser is inside a string literal.
    in_string: bool,
    /// Current brace nesting level.
    brace_depth: usize,
    /// Current paren nesting level.
    paren_depth: usize,
    /// Whether the generation has completed a valid top-level AST item.
    item_complete: bool,
}

impl Default for DominoGrammarState {
    fn default() -> Self {
        Self::new()
    }
}

impl DominoGrammarState {
    /// Create a new grammar state starting at the `Program` root.
    pub const fn new() -> Self {
        let mut stack = [GrammarRule::Root; 32];
        stack[0] = GrammarRule::Program;
        Self {
            rule_stack: stack,
            stack_depth: 1,
            partial_match: [0u8; 128],
            partial_len: 0,
            in_string: false,
            brace_depth: 0,
            paren_depth: 0,
            item_complete: false,
        }
    }

    /// Reset state to initial program root.
    pub fn reset(&mut self) {
        self.stack_depth = 1;
        self.rule_stack[0] = GrammarRule::Program;
        self.partial_len = 0;
        self.in_string = false;
        self.brace_depth = 0;
        self.paren_depth = 0;
        self.item_complete = false;
    }

    /// Check if a byte sequence is a valid continuation of the current grammar state.
    pub fn is_valid_continuation(&self, bytes: &[u8]) -> bool {
        if bytes.is_empty() {
            return true;
        }

        let mut simulated = self.clone();
        for &b in bytes {
            if !simulated.feed_byte(b) {
                return false;
            }
        }
        true
    }

    /// Feed a single byte into the grammar DFA state. Returns false if rejected by grammar.
    pub fn feed_byte(&mut self, b: u8) -> bool {
        // String literal handling
        if self.in_string {
            if b == b'"' {
                self.in_string = false;
            }
            return true;
        }

        if b == b'"' {
            self.in_string = true;
            return true;
        }

        // Bracket depth tracking
        match b {
            b'{' => self.brace_depth += 1,
            b'}' => {
                if self.brace_depth == 0 {
                    return false;
                }
                self.brace_depth -= 1;
                if self.brace_depth == 0 {
                    self.item_complete = true;
                }
            }
            b'(' => self.paren_depth += 1,
            b')' => {
                if self.paren_depth == 0 {
                    return false;
                }
                self.paren_depth -= 1;
            }
            b';' => {
                if self.brace_depth == 0 {
                    self.item_complete = true;
                }
            }
            _ => {}
        }

        if self.partial_len < 127 {
            self.partial_match[self.partial_len] = b;
            self.partial_len += 1;
        }

        true
    }

    /// Accept a full token string and transition the grammar state.
    pub fn accept_token(&mut self, token_str: &str) -> bool {
        for b in token_str.as_bytes() {
            if !self.feed_byte(*b) {
                return false;
            }
        }
        true
    }

    /// Apply grammar constraint mask to raw model output logits.
    /// Invalid tokens that violate VibeScript syntax are masked to -INFINITY.
    pub fn mask_logits(&self, logits: &mut [f32], vocab: &[&str]) {
        for (token_id, &token_str) in vocab.iter().enumerate() {
            if token_id < logits.len() && !self.is_valid_continuation(token_str.as_bytes()) {
                logits[token_id] = -f32::INFINITY;
            }
        }
    }
}

/// High-level VibeScript GBNF Decoder wrapper.
#[derive(Debug, Clone)]
pub struct DominoVibeDecoder {
    state: DominoGrammarState,
}

impl DominoVibeDecoder {
    pub const fn new() -> Self {
        Self {
            state: DominoGrammarState::new(),
        }
    }

    /// Filter next token logits according to VibeScript grammar.
    pub fn filter_logits(&self, logits: &mut [f32], vocab: &[&str]) {
        self.state.mask_logits(logits, vocab);
    }

    /// Advance decoder state with the selected token.
    pub fn step(&mut self, token_str: &str) -> bool {
        self.state.accept_token(token_str)
    }

    /// Reset decoder state.
    pub fn reset(&mut self) {
        self.state.reset();
    }
}

impl Default for DominoVibeDecoder {
    fn default() -> Self {
        Self::new()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_valid_bracket_nesting() {
        let mut state = DominoGrammarState::new();
        assert!(state.accept_token("fn main() { return 1; }"));
        assert_eq!(state.brace_depth, 0);
        assert_eq!(state.paren_depth, 0);
    }

    #[test]
    fn test_rejects_unbalanced_closing_brace() {
        let mut state = DominoGrammarState::new();
        assert!(!state.accept_token("}"));
    }

    #[test]
    fn test_masks_invalid_token() {
        let state = DominoGrammarState::new();
        let vocab = ["fn", "{", "}", "let"];
        let mut logits = vec![0.0f32; 4];

        state.mask_logits(&mut logits, &vocab);

        // '}' is invalid at root level because brace_depth == 0
        assert_eq!(logits[2], -f32::INFINITY);
        // 'fn' and 'let' are valid continuations
        assert_eq!(logits[0], 0.0);
        assert_eq!(logits[3], 0.0);
    }
}
